const escape = value => String(value).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const signed = value => `${value >= 0 ? '+' : '−'}${Math.abs(value).toFixed(5)}`;

export class DrawingReveal {
  constructor(root, { result, corpus, source, drawing, onAgain, onHuman, example = false }) {
    this.root = root; this.result = result; this.doc = result.ranking[0].doc;
    const target = corpus.documents[source.doc];
    const sourceRank = result.ranking.findIndex(item => item.doc === source.doc) + 1;
    const winner = result.ranking[0];
    root.innerHTML = `<div class="reveal-heading"><span class="handwritten">${example ? 'An example sketch · actual pixel-based inference' : 'No description. Just your drawing.'}</span><h1>The machine says…<br>${escape(winner.candidate.title)}.</h1><p>The source was <strong>${escape(target.title)}</strong>. ${winner.doc === source.doc ? 'It found the right article.' : `The source came ${sourceRank === 2 ? 'second' : sourceRank === 3 ? 'third' : `at rank ${sourceRank}`}. Let’s see what the model noticed.`}</p></div><section class="chain" aria-label="Drawing-only message chain"><article class="chain-item"><div class="paper-label"><span class="round">1</span>The secret passage</div><p>${escape(source.prompt)}</p><details><summary>Unedited source</summary><p>${escape(source.original)}</p></details><a href="${escape(target.url)}" target="_blank" rel="noopener">${escape(target.title)} · Wikipedia ↗</a></article><article class="chain-item"><div class="paper-label"><span class="round">2</span>${example ? 'The example drawing' : 'Your drawing'}</div><img src="${drawing}" alt="The sketch the image model received"></article><article class="chain-item"><div class="paper-label"><span class="round">3</span>The drawing-only guess</div><p class="description-quote">${escape(winner.candidate.title)}</p><p class="small" style="margin-top:15px">Cosine ${winner.score.toFixed(4)} · not confidence</p><p class="fineprint" style="margin-top:12px">The image encoder saw pixels. The retrieval stage used the same fixed candidate set as every other drawing, with no target ID or human description supplied.</p></article></section><section class="retrieval-panel"><div class="vision-results"><div><span class="handwritten">Its five best guesses</span><h2>From pixels to a possibility.</h2><p class="small muted">A vision–language model compares your drawing with three fixed text descriptions for each of 303 articles. Each article gets its best description’s cosine score. Click a guess to inspect its actual matching text.</p><div class="target-rank"><span class="rank-number">#${sourceRank}</span><p><strong>${escape(target.title)}</strong>Original article’s rank out of 303</p></div><ol class="rank-list">${result.ranking.slice(0, 5).map((item, i) => `<li class="rank-result ${item.doc === source.doc ? 'target' : ''}"><button data-vision-article="${item.doc}" aria-pressed="${i === 0}"><span class="place">${i + 1}</span><span class="result-name">${escape(item.candidate.title)}</span><span class="score">${item.score.toFixed(4)}</span></button></li>`).join('')}</ol></div><div class="vision-match"><span class="handwritten">What did it match?</span><h3 id="vision-match-name"></h3><p id="vision-match-text"></p><p class="fineprint">This is a candidate description written before the drawing was seen, not a caption generated from the image. Article names and source sentences are included in the candidate set.</p><a id="vision-source-link" target="_blank" rel="noopener">Read this article ↗</a></div></div><p class="retrieval-note">These are guesses within a fixed corpus, not open-ended recognition or calibrated probabilities. CLIP was trained on image–text pairs; simple sketches can be far outside the images it learned from. Read the matched description before trusting a result.</p></section><section class="mechanics vision-mechanics" aria-labelledby="vision-mechanics-title"><div class="mechanics-heading"><div><span class="handwritten">The picture has a vector, too.</span><h2 id="vision-mechanics-title">Open the image machine.</h2><p>This model puts images and text in one shared 512-dimensional space. The text-only game uses a different, 384-dimensional MiniLM space; those coordinates cannot be compared directly.</p></div></div><div class="vision-encoding"><div><div class="patch-preview" id="patch-preview"><img src="${result.preview}" alt="The actual 224 by 224 pixel input reconstructed from the model’s normalized pixels"><span class="patch-overlay" aria-hidden="true"></span></div><button id="toggle-patches" class="secondary" aria-pressed="false">Show the 32 × 32 pixel patches</button><p class="fineprint">The drawing is padded with white to a square, then resized to 224 × 224. Padding keeps the sketch’s edges from being cropped.</p></div><ol class="image-pipeline"><li><strong>1 · A smaller picture</strong><p>224 × 224 RGB pixels become 49 image patches, each 32 × 32 pixels.</p></li><li><strong>2 · A pretrained image encoder</strong><p>CLIP processes those patches and projects the image representation into 512 numbers.</p></li><li><strong>3 · Text in the same space</strong><p>A matching CLIP text encoder produced the candidate vectors offline. Each text input is limited to 77 tokens.</p></li><li><strong>4 · Normalize, multiply, add</strong><p>The image and text vectors have length 1. Summing their matching-coordinate products gives cosine similarity. The highest candidate score supplies each article’s score.</p></li></ol></div><label class="vision-compare-label" for="vision-compare">Inspect an article’s winning description<select id="vision-compare">${corpus.documents.map((article, doc) => `<option value="${doc}" ${doc === this.doc ? 'selected' : ''}>${escape(article.title)}${doc === source.doc ? ' · original' : ''}</option>`).join('')}</select></label><div id="vision-vector-inspector"></div><details class="math-detail"><summary>What is this model actually measuring?</summary><p>It measures compatibility between a drawing and candidate text in CLIP’s learned space. It does not read your intent or establish that a character is depicted correctly. The candidate set contains exactly three prototypes per article: an article-name prompt and two early source sentences selected using a fixed visual-vocabulary rule. The original article ID is used only after inference to report recovery rank.</p><p class="fineprint">Pinned model: <a href="https://huggingface.co/Xenova/clip-vit-base-patch32" target="_blank" rel="noopener">CLIP ViT-B/32</a>, revision ${escape(result.revision)}. Image and text encoders are quantized ONNX models; corpus text vectors are precomputed with the matching text encoder. The 89 MB image model runs in a worker in your browser. No drawing is uploaded.</p></details><div class="lesson-takeaway"><strong>Validate the instrument:</strong> the source article is known, so you can check recovery rank. One good guess is a case study, not an accuracy estimate. Try several different sketches and inspect failures.</div></section><div class="reveal-actions"><button id="vision-again" class="primary">Draw another passage</button><div class="toolrow"><button id="vision-human" class="secondary">Let a human try this drawing</button><button id="vision-save" class="secondary">Save the drawing & guesses</button></div></div>`;
    this.root.querySelectorAll('[data-vision-article]').forEach(button => button.addEventListener('click', () => { this.doc = Number(button.dataset.visionArticle); this.select(); }));
    this.el('#vision-compare').addEventListener('change', event => { this.doc = Number(event.target.value); this.select(); });
    this.el('#toggle-patches').addEventListener('click', event => {
      const show = event.currentTarget.getAttribute('aria-pressed') !== 'true';
      event.currentTarget.setAttribute('aria-pressed', show); this.el('#patch-preview').classList.toggle('show-patches', show);
    });
    this.el('#vision-again').addEventListener('click', onAgain);
    this.el('#vision-human').addEventListener('click', onHuman);
    this.el('#vision-save').addEventListener('click', () => {
      const payload = { mode: 'drawing-only', source: target.title, sourceUrl: target.url,
        sourceLicense: 'CC BY-SA 4.0', sourcePassage: source.original, drawingPrompt: source.prompt,
        drawing, model: result.model, revision: result.revision, sourceRank,
        topFive: result.ranking.slice(0, 5).map(item => ({ article: item.candidate.title, cosine: item.score, matchedText: item.candidate.prompt })),
        note: 'The image encoder received only pixels. Cosines are not calibrated confidence.' };
      const url = URL.createObjectURL(new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' }));
      const link = document.createElement('a'); link.href = url; link.download = 'pass-it-on-drawing-guesses.json'; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000);
    });
    this.corpus = corpus; this.select();
  }
  el(selector) { return this.root.querySelector(selector); }
  select() {
    const item = this.result.ranking.find(item => item.doc === this.doc);
    this.el('#vision-compare').value = String(this.doc);
    this.root.querySelectorAll('[data-vision-article]').forEach(button => button.setAttribute('aria-pressed', Number(button.dataset.visionArticle) === this.doc));
    this.el('#vision-match-name').textContent = item.candidate.title;
    this.el('#vision-match-text').textContent = item.candidate.prompt;
    this.el('#vision-source-link').href = this.corpus.documents[this.doc].url;
    const q = this.result.imageVector, d = item.vector;
    const grid = (vector, label) => {
      const max = Math.max(...vector.map(Math.abs));
      return `<div class="vector-row"><span class="vector-row-label">${label}</span><div class="vector-grid vision-grid" role="img" aria-label="${label}, all 512 coordinates. Blue is positive and pink is negative.">${vector.map((value, i) => `<i aria-hidden="true" data-vision-coordinate="${i}" style="--cell-color:${value >= 0 ? '#3444df' : '#c64c76'};--cell-opacity:${.12 + Math.abs(value) / max * .88}"></i>`).join('')}</div></div>`;
    };
    const products = q.map((value, i) => value * d[i]);
    const score = products.reduce((sum, value) => sum + value, 0);
    this.el('#vision-vector-inspector').innerHTML = `<div class="vision-cosine"><span class="handwritten">512 products. One cosine.</span><strong>${score.toFixed(4)}</strong><p>${escape(item.candidate.title)} · rank ${this.result.ranking.indexOf(item) + 1} of 303</p></div><div class="vector-legend"><strong>Image and matching text vector</strong><span><i class="positive-key"></i>Positive <i class="negative-key"></i>Negative</span></div>${grid(q, 'Drawing')}${grid(d, 'Candidate text')}<label for="vision-dimension" class="dimension-label">Inspect a multiplication <output id="vision-coordinate-label">1 / 512</output></label><input class="dimension-slider" id="vision-dimension" type="range" min="1" max="512" value="1"><div class="coordinate-equation" id="vision-coordinate"></div><p class="fineprint">This is coordinate order, not an image or a 2D map. Color intensity is scaled separately for each row; the slider gives actual values.</p><details class="math-detail"><summary>See all 512 coordinate products</summary><div class="math-table-wrap all-products"><table><thead><tr><th>Coordinate</th><th>Image</th><th>Text</th><th>Product</th></tr></thead><tbody>${products.map((product, i) => `<tr><th>${i + 1}</th><td>${signed(q[i])}</td><td>${signed(d[i])}</td><td>${signed(product)}</td></tr>`).join('')}</tbody><tfoot><tr><th colspan="3">Sum of unrounded products</th><td>${score.toFixed(6)}</td></tr></tfoot></table></div></details>`;
    const coordinate = i => {
      this.el('#vision-coordinate-label').textContent = `${i + 1} / 512`;
      this.el('#vision-coordinate').innerHTML = `<span>${signed(q[i])}</span><b>×</b><span>${signed(d[i])}</span><b>=</b><strong>${signed(products[i])}</strong>`;
      this.root.querySelectorAll('[data-vision-coordinate]').forEach(cell => cell.classList.toggle('selected-coordinate', Number(cell.dataset.visionCoordinate) === i));
    };
    this.el('#vision-dimension').addEventListener('input', event => coordinate(Number(event.target.value) - 1)); coordinate(0);
  }
}
